import type { Text } from './authored-builder';
export const tx = (en: string, fr: string): Text => ({ en, fr });
export interface JhsPreviewUnit {
  id: string;
  subskills?: string[];
  misconception?: string;
  title: Text;
  explanation: Text;
  example: Text;
  question: Text;
  options: { en: string[]; fr: string[] };
  correction: Text;
  tasks: [Text, Text];
  transfer: [Text, Text];
  retention: [Text, Text];
  retentionOptions: [{ en: string[]; fr: string[] }, { en: string[]; fr: string[] }];
  criteria: Text[];
}

const register = (grade: 7 | 8 | 9, page: string, example: Text, tasks: [Text, Text], transfer: [Text, Text]): JhsPreviewUnit => ({
  id: `competency-gh-english-b${grade}-nacca2020-p${page}-r01`,
  title: tx('Choosing language for your audience', 'Choisir le langage selon son public'),
  explanation: tx('Your learning goal is to choose an appropriate register and use it in conversation. Register depends on your relationship, purpose and setting. A friendly greeting suits a classmate; a polite introduction and clear request suit a school office. Informal speech is not automatically wrong. Listen, respond to your partner and explain your choice. French supports the explanation here; the English Language performance itself must be demonstrated in English. Reading or choosing a line does not establish speaking competence.', 'Ton objectif est de choisir un registre adapté et de l’utiliser dans une conversation. Le registre dépend de la relation, du but et du contexte. Une salutation familière convient à un camarade ; une présentation polie et une demande claire conviennent au secrétariat. Le langage familier n’est pas toujours incorrect. Écoute, réponds et justifie ton choix. Le français aide à comprendre ; la compétence orale d’anglais doit être démontrée en anglais. Lire ou sélectionner une phrase ne prouve pas cette compétence.'),
  example,
  question: tx('You are asking the headteacher for permission. Which opening best suits this formal situation?', 'Tu demandes une autorisation à la direction. Quelle formule convient à cette situation formelle ?'),
  options: { en: ['Good morning. May I explain our request, please?', 'Hey mate, just do this.', 'No need to explain.'], fr: ['Good morning. May I explain our request, please?', 'Hey mate, just do this.', 'No need to explain.'] },
  correction: tx('First identify the audience and purpose. A headteacher receiving an official request calls for a respectful greeting and clear request. “Hey mate” can signal familiarity between friends, but does not suit this example. Say the formal opening aloud, then try again. In the oral task, your teacher must hear your own English, not just see a selected answer.', 'Identifie d’abord le destinataire et le but. Une demande officielle à la direction appelle une salutation respectueuse et une demande claire. « Hey mate » peut signaler une familiarité entre amis, mais ne convient pas ici. Dis la formule formelle à voix haute, puis réessaie. Pour l’évaluation orale, l’enseignant doit entendre ton anglais personnel, pas seulement voir une réponse choisie.'),
  tasks, transfer,
  retention: [tx('Which factor helps you choose a register?', 'Quel élément aide à choisir le registre ?'), tx('Does selecting a polite sentence prove that you can hold an English conversation?', 'Choisir une phrase polie prouve-t-il que tu sais converser en anglais ?')],
  retentionOptions: [{ en: ['Audience, purpose and setting', 'Only the length of the sentence', 'Only how loudly I speak'], fr: ['Le public, le but et le contexte', 'Seulement la longueur de la phrase', 'Seulement le volume de la voix'] }, { en: ['No; an actual conversation must be observed', 'Yes; no speaking is needed', 'Yes; a click proves all oral skills'], fr: ['Non ; il faut observer une vraie conversation', 'Oui ; parler est inutile', 'Oui ; un clic prouve toutes les compétences orales'] }],
  criteria: [tx('Hear the learner’s actual English conversation, including spontaneous responses; a written script alone is insufficient.', 'Écouter la vraie conversation en anglais, y compris les réponses spontanées ; un texte seul ne suffit pas.'), tx('Check register against audience and situation, intelligibility, listening and the learner’s explanation of choices.', 'Vérifier le registre selon le public et le contexte, l’intelligibilité, l’écoute et la justification des choix.')],
});

export const JHS_PREVIEW_UNITS: JhsPreviewUnit[] = [
  {
    id: 'competency-gh-computing-b8-nacca2020-p054-r01', title: tx('Choosing an output device', 'Choisir un périphérique de sortie'),
    explanation: tx('Output devices communicate processed information. A Braille embosser produces raised dots for reading by touch. An impact printer strikes a ribbon against paper; an inkjet sprays droplets. A thermal printer uses heat, commonly on heat-sensitive receipt paper. A wax or solid-ink printer melts solid colour material for printing. A 3D printer builds a physical object layer by layer from a digital design. Compare purpose, medium, accessibility and running needs rather than assuming one printer suits every job. Study approved images or videos; do not touch hot parts or operate equipment without supervision.', 'Un périphérique de sortie communique des informations traitées. Une embosseuse braille produit des points en relief lisibles au toucher. Une imprimante à impact frappe un ruban sur le papier ; une jet d’encre projette des gouttelettes. Une imprimante thermique utilise la chaleur, souvent sur du papier sensible pour tickets. Une imprimante à cire ou à encre solide fait fondre de la matière colorée solide. Une imprimante 3D construit un objet couche par couche à partir d’un modèle numérique. Compare but, support, accessibilité et besoins d’utilisation. Étudie des images ou vidéos approuvées ; ne touche aucune partie chaude et n’utilise pas l’équipement sans supervision.'),
    example: tx('A school needs a tactile text for a Braille reader, a colour notice and a physical model. An embosser suits the tactile text, an inkjet may suit the colour notice, and a 3D printer can make an appropriate physical model. Check the actual reader’s needs and available equipment. Printing an image of Braille dots in flat ink does not make it tactile Braille.', 'Une école souhaite un texte tactile pour une personne lisant le braille, une affiche couleur et un modèle physique. Une embosseuse convient au texte tactile, une jet d’encre peut convenir à l’affiche et une imprimante 3D au modèle adapté. Vérifie les besoins réels du lecteur et le matériel disponible. Une image de points braille imprimée à plat n’est pas du braille tactile.'),
    question: tx('Which device produces raised Braille dots on paper?', 'Quel appareil produit des points braille en relief sur le papier ?'), options: { en: ['A Braille embosser', 'An ordinary flat-ink printout of dots', 'A keyboard alone'], fr: ['Une embosseuse braille', 'Une impression de points à plat', 'Un clavier seul'] },
    correction: tx('Focus on the output needed: raised dots must be felt, not merely seen. An embosser changes the paper surface. A flat image of dots does not provide the same tactile information. Match the device to the user’s actual access needs and retry.', 'Concentre-toi sur la sortie nécessaire : les points doivent être ressentis, pas seulement vus. Une embosseuse modifie le relief du papier. Une image de points à plat n’offre pas la même information tactile. Adapte l’appareil aux besoins réels, puis réessaie.'),
    tasks: [tx('Using teacher-approved pictures or videos, identify Braille, impact, inkjet, thermal, wax/solid-ink and 3D printers. Make your own comparison table of how each works, output medium and a suitable real-life use. Explain accessibility and safety considerations. Your teacher must inspect the actual table and question your choices.', 'À partir d’images ou vidéos approuvées, identifie les imprimantes braille, à impact, à jet d’encre, thermiques, à cire/encre solide et 3D. Fais ton propre tableau du fonctionnement, du support et d’un usage réel adapté. Explique accessibilité et sécurité. L’enseignant examine le tableau et interroge tes choix.'), tx('Independently choose output devices for a tactile school document, a shop receipt, a colour school poster and a physical model. Explain alternatives and limitations, then describe the remaining printer types from the lesson using approved images. Submit your own annotated comparison for review.', 'Choisis seul des appareils pour un document scolaire tactile, un ticket de magasin, une affiche couleur et un modèle physique. Justifie les alternatives et limites, puis décris les autres types étudiés avec des images approuvées. Présente ta comparaison personnelle annotée.')],
    transfer: [tx('A teacher supplies a new school output need and equipment constraints. Independently recommend a printer, justify accessibility and running needs, compare an alternative and state what further information you need. Do not claim to have operated equipment you only saw in a picture.', 'L’enseignant fournit un nouveau besoin scolaire et des contraintes de matériel. Recommande seul une imprimante, justifie accessibilité et besoins d’utilisation, compare une alternative et précise les informations manquantes. Ne prétends pas avoir utilisé un appareil seulement vu en image.'), tx('Explain why a 3D model, a printed colour image and a tactile Braille page are different outputs. Propose an appropriate local use for each and defend your choices to your teacher.', 'Explique les différences entre modèle 3D, image couleur imprimée et page braille tactile. Propose un usage local adapté à chacun et justifie tes choix à l’enseignant.')],
    retention: [tx('Which process builds an object layer by layer?', 'Quel procédé construit un objet couche par couche ?'), tx('Which printer commonly uses heat-sensitive receipt paper?', 'Quelle imprimante utilise couramment du papier thermique pour tickets ?')],
    retentionOptions: [{ en: ['3D printing', 'Typing only', 'Ordinary flat photocopying'], fr: ['L’impression 3D', 'La saisie seule', 'La photocopie plane ordinaire'] }, { en: ['Thermal printer', 'Braille embosser only', '3D printer only'], fr: ['L’imprimante thermique', 'Uniquement l’embosseuse braille', 'Uniquement l’imprimante 3D'] }],
    criteria: [tx('Inspect the actual six-device comparison and oral justification against approved images or videos.', 'Examiner la vraie comparaison des six appareils et la justification orale avec des images ou vidéos approuvées.'), tx('Require accurate features, appropriate real-life uses and accessibility reasoning without claiming practical operation from picture recognition.', 'Exiger des caractéristiques exactes, des usages adaptés et une justification d’accessibilité sans confondre reconnaissance d’image et utilisation pratique.')],
  },
  {
    id: 'competency-gh-computing-b9-nacca2020-p070-r02', title: tx('Perceptual computing', 'Informatique perceptuelle'),
    explanation: tx('Perceptual computing uses information about human actions or surroundings to support interaction: for example voice, gestures or visual signals captured by suitable sensors. A microphone supplies sound data; recognition software interprets a pattern and an application decides a response. A sensor alone does not understand a person’s intention. Recognition can fail because of noise, lighting, language variation or ambiguous gestures. Discuss accessibility, privacy and consent. Use fictional diagrams or teacher-approved demonstrations; do not collect classmates’ voices, faces or other personal data for this activity.', 'L’informatique perceptuelle utilise des informations sur les actions humaines ou l’environnement pour faciliter l’interaction : voix, gestes ou signaux visuels captés par des capteurs adaptés, par exemple. Un microphone fournit des données sonores ; un logiciel reconnaît un motif et une application choisit une réponse. Un capteur seul ne comprend pas l’intention. Le bruit, la lumière, les variations linguistiques ou les gestes ambigus peuvent provoquer des erreurs. Discute accessibilité, confidentialité et consentement. Utilise des schémas fictifs ou des démonstrations approuvées ; ne collecte pas la voix, le visage ou d’autres données personnelles des camarades.'),
    example: tx('In a fictional voice-controlled classroom timer, the microphone captures sound, software recognises “start timer”, and the application starts a countdown. Background conversation may be misrecognised, so a visible confirmation and manual control help. Draw capture → interpretation → action, and distinguish the sensor from the software decision.', 'Dans un minuteur scolaire fictif commandé par la voix, le microphone capte le son, le logiciel reconnaît « démarre le minuteur » et l’application lance le compte à rebours. Une conversation peut être mal reconnue ; une confirmation visible et une commande manuelle aident. Dessine capture → interprétation → action et distingue capteur et décision logicielle.'),
    question: tx('In the timer example, what interprets the spoken command?', 'Dans l’exemple du minuteur, qu’est-ce qui interprète la commande orale ?'), options: { en: ['Recognition software', 'The microphone without any software', 'The speaker’s loudness alone'], fr: ['Le logiciel de reconnaissance', 'Le microphone sans aucun logiciel', 'Seulement le volume de la voix'] },
    correction: tx('Trace the chain. The microphone captures sound; software interprets its pattern; the application acts. Capturing sound and understanding a command are different steps. Explain a possible recognition error, then retry.', 'Suis la chaîne. Le microphone capte le son, le logiciel interprète le motif et l’application agit. Capter un son et interpréter une commande sont deux étapes différentes. Explique une erreur possible, puis réessaie.'),
    tasks: [tx('Independently explain perceptual computing using one voice and one gesture example. Draw sensor-input, interpretation and action for each, discuss features, possible errors, accessibility, privacy and manual alternatives. Your teacher must inspect the diagrams and hear your reasoning; no personal recordings are needed.', 'Explique seul l’informatique perceptuelle avec un exemple vocal et un exemple gestuel. Dessine capteur/entrée, interprétation et action pour chacun ; discute caractéristiques, erreurs, accessibilité, confidentialité et commandes manuelles. L’enseignant examine les schémas et écoute ton raisonnement ; aucun enregistrement personnel n’est nécessaire.'), tx('Compare a fictional gesture-controlled presentation with an ordinary keyboard-controlled presentation. Explain what is perceived, how interpretation can fail and when each is appropriate. Present your own annotated comparison for teacher review.', 'Compare une présentation fictive commandée par gestes et une autre commandée au clavier. Explique ce qui est perçu, les erreurs possibles et les usages adaptés. Présente ta comparaison personnelle annotée à l’enseignant.')],
    transfer: [tx('For a new teacher-provided school scenario, propose a perceptual interface. Identify sensors, interpretation and action, an error case and a fallback. Explain privacy and access choices using a fictional diagram, without gathering personal data.', 'Pour une nouvelle situation scolaire fournie par l’enseignant, propose une interface perceptuelle. Indique capteurs, interprétation, action, erreur possible et solution de repli. Justifie confidentialité et accès avec un schéma fictif, sans collecte de données personnelles.'), tx('A classmate says a camera always understands what a person wants. Explain the limits using a new perceptual-computing example and propose a confirmation step. Defend your reasoning to your teacher.', 'Un camarade dit qu’une caméra comprend toujours les intentions. Explique les limites avec un nouvel exemple d’informatique perceptuelle et propose une confirmation. Justifie ton raisonnement à l’enseignant.')],
    retention: [tx('Which can reduce voice recognition reliability?', 'Qu’est-ce qui peut réduire la fiabilité de la reconnaissance vocale ?'), tx('Why provide a manual alternative?', 'Pourquoi proposer une commande manuelle ?')],
    retentionOptions: [{ en: ['Background noise', 'Every sensor is always perfect', 'Software never interprets patterns'], fr: ['Le bruit de fond', 'Tous les capteurs sont parfaits', 'Les logiciels n’interprètent jamais de motifs'] }, { en: ['Recognition may fail or not suit a user', 'To prove sensors read minds', 'Because privacy never matters'], fr: ['La reconnaissance peut échouer ou ne pas convenir', 'Pour prouver que les capteurs lisent les pensées', 'Parce que la confidentialité ne compte jamais'] }],
    criteria: [tx('Inspect independent diagrams and discussion of perceptual inputs, recognition features and application responses.', 'Examiner les schémas et la discussion autonomes des entrées perceptuelles, de la reconnaissance et des réponses de l’application.'), tx('Check recognition limits, appropriate comparisons and justified access/privacy considerations; no invented demonstration or personal-data collection.', 'Vérifier les limites, les comparaisons et les choix d’accès/confidentialité justifiés ; aucune démonstration inventée ni collecte de données personnelles.')],
  },
  {
    id: 'competency-gh-science-b8-nacca2020-p091-r01', title: tx('Inside an atom', 'À l’intérieur d’un atome'),
    explanation: tx('An atom has a small nucleus containing protons and, in most atoms, neutrons. Electrons occupy the space around the nucleus. A proton has positive charge, an electron negative charge and a neutron no net charge. The atomic number Z is the number of protons and identifies an element on the periodic table. For a neutral atom, electrons equal protons. The mass number A is protons plus neutrons, so neutrons = A − Z. A simple drawn shell model helps us count; it does not show the true size or motion of particles. Do not confuse mass number for a specified isotope with the average atomic mass printed on many periodic tables.', 'Un atome possède un petit noyau contenant des protons et, dans la plupart des atomes, des neutrons. Les électrons occupent l’espace autour du noyau. Le proton est positif, l’électron négatif et le neutron n’a pas de charge nette. Le numéro atomique Z est le nombre de protons et identifie l’élément dans le tableau périodique. Dans un atome neutre, électrons et protons sont aussi nombreux. Le nombre de masse A compte protons et neutrons : neutrons = A − Z. Un modèle simple en couches aide au comptage sans représenter la taille réelle ni le mouvement des particules. Ne confonds pas le nombre de masse d’un isotope donné avec la masse atomique moyenne souvent imprimée dans le tableau.'),
    example: tx('For a neutral carbon atom with Z = 6 and A = 14, there are 6 protons, 14 − 6 = 8 neutrons and 6 electrons. Locate carbon on a teacher-approved periodic table using Z = 6. Draw and label the nucleus and electrons, marking charges. The number 14 specifies this atom’s mass number; do not round an average table mass to invent it.', 'Pour un atome de carbone neutre de Z = 6 et A = 14 : 6 protons, 14 − 6 = 8 neutrons et 6 électrons. Repère le carbone avec Z = 6 dans un tableau approuvé. Dessine et légende noyau et électrons, avec les charges. Le nombre 14 est le nombre de masse donné ici ; ne l’invente pas en arrondissant une masse moyenne.'),
    question: tx('Which particle count defines the atomic number?', 'Quel nombre de particules définit le numéro atomique ?'), options: { en: ['Number of protons', 'Number of neutrons alone', 'Protons plus neutrons'], fr: ['Le nombre de protons', 'Le nombre de neutrons seulement', 'Protons plus neutrons'] },
    correction: tx('Separate Z from A. Z counts protons only; A adds protons and neutrons. For carbon-14, Z is 6 and A is 14. Locate each particle and its charge before trying again.', 'Distingue Z et A. Z compte seulement les protons ; A additionne protons et neutrons. Pour le carbone 14, Z vaut 6 et A vaut 14. Repère chaque particule et sa charge avant de réessayer.'),
    tasks: [tx('Using a teacher-approved periodic table, locate carbon (Z=6) and oxygen (Z=8). For neutral atoms with A=12 and A=16 respectively, independently calculate all three particle counts, draw labelled models and explain locations and charges. Show your work and discuss the model’s limits with your teacher.', 'Avec un tableau périodique approuvé, repère carbone (Z=6) et oxygène (Z=8). Pour des atomes neutres de A=12 et A=16 respectivement, calcule seul les trois nombres de particules, dessine des modèles légendés et explique positions et charges. Présente le travail et les limites du modèle à l’enseignant.'), tx('For neutral sodium with Z=11, A=23 and neutral magnesium with Z=12, A=24, calculate protons, neutrons and electrons. Locate each element on a periodic table, compare atomic and mass numbers and explain all particle charges independently.', 'Pour le sodium neutre Z=11, A=23 et le magnésium neutre Z=12, A=24, calcule protons, neutrons et électrons. Repère les éléments dans le tableau, distingue numéro atomique et nombre de masse et explique seul les charges.')],
    transfer: [tx('Your teacher supplies a new neutral atom with Z and A. Independently predict particle counts, identify its element on the periodic table and explain why A cannot be smaller than Z. Submit an annotated model.', 'L’enseignant fournit un nouvel atome neutre avec Z et A. Prévois seul les nombres de particules, trouve l’élément dans le tableau et explique pourquoi A ne peut pas être inférieur à Z. Présente un modèle annoté.'), tx('Compare neutral carbon-12 and carbon-14 using Z=6. Explain what stays the same and what changes, with labelled models. Do not infer that they are different elements just because their mass numbers differ.', 'Compare carbone 12 et carbone 14 neutres avec Z=6. Explique les constantes et les différences avec des modèles légendés. Ne conclus pas qu’il s’agit d’éléments différents à cause de nombres de masse différents.')],
    retention: [tx('For a neutral atom with Z=8 and A=16, how many neutrons are there?', 'Pour un atome neutre Z=8 et A=16, combien y a-t-il de neutrons ?'), tx('Where are electrons in a simple atomic model?', 'Où sont les électrons dans un modèle simple ?')],
    retentionOptions: [{ en: ['8', '16', '24'], fr: ['8', '16', '24'] }, { en: ['Around the nucleus', 'Only inside protons', 'They are the same as neutrons'], fr: ['Autour du noyau', 'Seulement dans les protons', 'Ce sont les mêmes particules que les neutrons'] }],
    criteria: [tx('Inspect actual independent counts, periodic-table identification and labelled models with correct locations and charges.', 'Examiner les vrais calculs autonomes, l’identification dans le tableau et les modèles légendés avec positions et charges exactes.'), tx('Check Z/A distinctions, neutrality and acknowledgement of model limits; no quiz-only certification.', 'Vérifier les distinctions Z/A, la neutralité et les limites du modèle ; aucune certification fondée uniquement sur un quiz.')],
  },
  {
    id: 'competency-gh-science-b9-nacca2020-p124-r02', title: tx('How binary compounds form', 'Formation des composés binaires'),
    explanation: tx('An element contains one type of atom. A molecule is a bonded group of atoms; it can be an element such as O₂ or a compound such as H₂O. An ion is a charged atom or group. A binary compound contains exactly two elements, not necessarily two atoms. H₂O has two hydrogen atoms and one oxygen atom: three atoms but two elements. Atoms can form covalent bonds by sharing electrons, or form ions whose opposite charges attract in an ionic structure. Sodium chloride is an ionic lattice, not a collection of individual NaCl molecules. Use safe paper or reusable models; no chemical reactions are required in this lesson.', 'Un élément contient un seul type d’atome. Une molécule est un groupe d’atomes liés ; elle peut représenter un élément comme O₂ ou un composé comme H₂O. Un ion est un atome ou groupe chargé. Un composé binaire contient exactement deux éléments, pas forcément deux atomes. H₂O possède deux atomes d’hydrogène et un d’oxygène : trois atomes mais deux éléments. Une liaison covalente partage des électrons ; une structure ionique associe des ions de charges opposées. Le chlorure de sodium est un réseau ionique, pas un ensemble de molécules NaCl individuelles. Utilise des modèles sûrs en papier ou réutilisables ; aucune réaction chimique n’est demandée.'),
    example: tx('Make a water model with two labelled H pieces and one O piece. The formula H₂O records their ratio, and covalent bonds connect the atoms. Compare magnesium oxide: Mg²⁺ and O²⁻ balance in a 1:1 ratio, written MgO; represent a small repeating ionic arrangement rather than a water-like molecule. Both are binary compounds. Models show composition and connections, not real colours or sizes.', 'Fabrique un modèle d’eau avec deux pièces H et une pièce O. H₂O indique les proportions et des liaisons covalentes relient les atomes. Compare l’oxyde de magnésium : Mg²⁺ et O²⁻ s’équilibrent dans le rapport 1:1, écrit MgO ; représente un petit réseau répété plutôt qu’une molécule semblable à l’eau. Les deux composés sont binaires. Les modèles indiquent composition et liens, pas couleurs ou dimensions réelles.'),
    question: tx('Why is H₂O a binary compound?', 'Pourquoi H₂O est-il un composé binaire ?'), options: { en: ['It contains two different elements', 'It contains exactly two atoms', 'It is a mixture of unbonded gases'], fr: ['Il contient deux éléments différents', 'Il contient exactement deux atomes', 'C’est un mélange de gaz non liés'] },
    correction: tx('Count element symbols separately from atom counts. H and O are two elements; H₂O has three atoms per molecule. “Binary” counts elements. A compound has chemically combined constituents, unlike a simple unbonded mixture. Rebuild the model and retry.', 'Compte les symboles des éléments séparément des atomes. H et O sont deux éléments ; H₂O possède trois atomes par molécule. « Binaire » compte les éléments. Un composé possède des constituants liés chimiquement, contrairement à un simple mélange. Refais le modèle, puis réessaie.'),
    tasks: [tx('Independently distinguish element, molecule, ion and compound using examples. Write H₂O, CO₂, FeS and MgO, and make safe labelled models of water, carbon(IV) oxide, iron(II) sulphide and magnesium oxide. Explain composition, covalent sharing versus ionic attraction, and the limits of the models. Your teacher must inspect the actual models and hear your explanation.', 'Distingue seul élément, molécule, ion et composé avec des exemples. Écris H₂O, CO₂, FeS et MgO et fabrique des modèles sûrs légendés de l’eau, du dioxyde de carbone, du sulfure de fer(II) et de l’oxyde de magnésium. Explique composition, partage covalent, attraction ionique et limites. L’enseignant doit voir les vrais modèles et écouter tes explications.'), tx('Compare the composition and bonding of water and magnesium oxide, then compare their properties using teacher-provided verified information. Explain why a formula ratio is not always a separate molecule. Show your own diagrams and actual models; do not perform reactions.', 'Compare la composition et les liaisons de l’eau et de l’oxyde de magnésium, puis leurs propriétés avec des informations vérifiées fournies par l’enseignant. Explique pourquoi un rapport de formule ne correspond pas toujours à une molécule distincte. Montre tes schémas et vrais modèles ; ne réalise aucune réaction.')],
    transfer: [tx('Use a teacher-approved new binary compound formula. Independently identify its elements, interpret its ratio, decide whether a molecule or ionic arrangement is appropriate from supplied bonding information, and construct a safe labelled model with limitations.', 'Avec la formule approuvée d’un nouveau composé binaire, identifie seul les éléments, interprète les proportions, choisis molécule ou réseau selon les informations de liaison fournies et construis un modèle sûr légendé avec ses limites.'), tx('A learner says CO₂ is not binary because it has three atoms. Correct the explanation with your own model, compare it with an ionic compound already studied and justify the difference to your teacher.', 'Un élève dit que CO₂ n’est pas binaire car il a trois atomes. Corrige l’explication avec ton propre modèle, compare avec un composé ionique déjà étudié et justifie la différence à l’enseignant.')],
    retention: [tx('Which of these symbols represents an ion with an electrical charge?', 'Lequel de ces symboles représente un ion portant une charge électrique ?'), tx('What does the 2 in CO₂ indicate?', 'Qu’indique le 2 dans CO₂ ?')],
    retentionOptions: [{ en: ['Na⁺', 'An uncharged oxygen atom', 'A paper label alone'], fr: ['Na⁺', 'Un atome d’oxygène neutre', 'Une étiquette en papier seule'] }, { en: ['Two oxygen atoms per molecule', 'Two different carbon elements', 'Two separate mixtures'], fr: ['Deux atomes d’oxygène par molécule', 'Deux éléments carbone différents', 'Deux mélanges séparés'] }],
    criteria: [tx('Inspect actual independently made models, formulas and explanations of element/molecule/ion/compound distinctions and compound formation.', 'Examiner les vrais modèles autonomes, les formules et les explications distinguant élément, molécule, ion et composé ainsi que la formation des composés.'), tx('Check composition, appropriate molecular versus ionic representations, source-supported property comparisons and explicit model limitations.', 'Vérifier composition, représentations moléculaires ou ioniques appropriées, comparaisons de propriétés documentées et limites explicites des modèles.')],
  },
  {
    id: 'competency-gh-mathematics-b8-nacca2020-p120-r01', title: tx('Reading and writing numbers beyond a billion', 'Lire et écrire des nombres au-delà du milliard'),
    explanation: tx('Group digits in threes from the right: billions | millions | thousands | ones. Read each group with its place name, keeping zero placeholders. In 2,408,321,507 the groups are 2 | 408 | 321 | 507. The 8 is in the millions place, so its value is 8,000,000. English “billion” here means 1,000,000,000, called “milliard” in French. Both languages name the same quantity. Read the numeral aloud, then write the number in words and reverse the process.', 'Groupe les chiffres par trois depuis la droite : milliards | millions | milliers | unités. Lis chaque groupe avec son nom et conserve les zéros de position. Dans 2 408 321 507, les groupes sont 2 | 408 | 321 | 507. Le 8 vaut 8 000 000. Le mot anglais « billion » désigne ici 1 000 000 000, soit un « milliard » en français. Les deux langues nomment la même quantité. Lis le nombre à voix haute, écris-le en lettres, puis fais l’inverse.'),
    example: tx('2 | 408 | 321 | 507 reads “two billion, four hundred and eight million, three hundred and twenty-one thousand, five hundred and seven”. Checking the groups prevents 408 million becoming 48 million. For 1,005,000,010 keep the zero thousands group: one billion, five million and ten.', '2 | 408 | 321 | 507 se lit « deux milliards quatre cent huit millions trois cent vingt et un mille cinq cent sept ». Vérifier les groupes évite de transformer 408 millions en 48 millions. Pour 1 005 000 010, conserve le groupe nul des milliers : un milliard cinq millions dix.'),
    question: tx('What is the value of the digit 8 in 2,408,321,507?', 'Quelle est la valeur du chiffre 8 dans 2 408 321 507 ?'), options: { en: ['8,000,000', '800,000', '8'], fr: ['8 000 000', '800 000', '8'] },
    correction: tx('Write the three-digit groups first. The group 408 names millions: 400 million + 8 million. A digit’s value depends on its position, not just its face value. Point to the millions column and retry.', 'Écris d’abord les groupes de trois chiffres. Le groupe 408 désigne des millions : 400 millions + 8 millions. La valeur dépend de la position du chiffre, pas seulement de son nom. Repère la colonne des millions et réessaie.'),
    tasks: [tx('Independently read 3,062,405,019 and 1,700,008,002 aloud to your teacher, write both in words and expand their place values. Explain the zeros. Submit the actual written work for review.', 'Lis seul 3 062 405 019 et 1 700 008 002 à voix haute à l’enseignant, écris-les en lettres et décompose leurs valeurs. Explique les zéros. Présente ton vrai travail écrit.'), tx('Write numerals for “four billion, twenty million, six thousand and nine” and “two billion, five hundred million and forty”. Read them back and justify each three-digit group. Teacher review is required.', 'Écris en chiffres « quatre milliards vingt millions six mille neuf » et « deux milliards cinq cents millions quarante ». Relis-les et justifie chaque groupe. Examen par l’enseignant requis.')],
    transfer: [tx('Create two fictional quantities above one billion with zero groups in different positions. Exchange written number names with a partner, independently reconstruct the numerals and explain any disagreement to your teacher.', 'Crée deux quantités fictives supérieures à un milliard, avec des groupes nuls à des positions différentes. Échange les noms écrits avec un partenaire, retrouve seul les nombres et explique tout désaccord à l’enseignant.'), tx('A fictional science data table records 6,030,002,400 particles. Read and write it in words, identify the value of 3 and explain why removing a zero changes the quantity. Show your own reasoning.', 'Un tableau scientifique fictif indique 6 030 002 400 particules. Lis et écris le nombre en lettres, précise la valeur de 3 et explique pourquoi supprimer un zéro change la quantité. Présente ton raisonnement.')],
    retention: [tx('What does the group 005 represent in 1 | 005 | 000 | 010?', 'Que représente le groupe 005 dans 1 | 005 | 000 | 010 ?'), tx('Which numeral means one billion, five million and ten?', 'Quel nombre signifie un milliard cinq millions dix ?')],
    retentionOptions: [{ en: ['Five million', 'Five thousand', 'Five billion'], fr: ['Cinq millions', 'Cinq mille', 'Cinq milliards'] }, { en: ['1,005,000,010', '1,050,000,010', '1,005,010'], fr: ['1 005 000 010', '1 050 000 010', '1 005 010'] }],
    criteria: [tx('Check actual spoken reading, written number names, numeral reconstruction and place-value explanation, including zero groups.', 'Vérifier la lecture orale réelle, l’écriture en lettres, les nombres retrouvés et les explications des positions, y compris les groupes nuls.'), tx('Accept equivalent correct language conventions while requiring the same numerical quantity; French milliard and English billion must agree.', 'Accepter les formulations correctes équivalentes en exigeant la même quantité ; milliard français et billion anglais doivent correspondre.')],
  },
  {
    id: 'competency-gh-mathematics-b9-nacca2020-p195-r01', title: tx('Significant figures and decimal places', 'Chiffres significatifs et décimales'),
    explanation: tx('Significant figures count from the first non-zero digit; decimal places count positions after the decimal point. To round, keep the requested digits, inspect the next digit and choose the nearest value. Replace dropped whole-number places with zeros so the magnitude is preserved. For decimal rounding, omit unwanted decimal places after deciding whether the last retained digit increases. These are different instructions: three significant figures need not mean three decimal places.', 'Les chiffres significatifs se comptent depuis le premier chiffre non nul ; les décimales sont les positions après la virgule. Pour arrondir, garde les chiffres demandés, regarde le suivant et choisis la valeur la plus proche. Remplace les positions entières abandonnées par des zéros pour garder l’ordre de grandeur. Pour les décimales, retire les positions inutiles après avoir décidé si le dernier chiffre conservé augmente. Trois chiffres significatifs ne signifient pas forcément trois décimales.'),
    example: tx('857,386,321 to three significant figures keeps 857; the next digit is 3, so the result is 857,000,000. For 98,745.9674 to two decimal places keep .96 and inspect 7: the answer is 98,745.97. To one decimal place, .9 rounds with a carry to 98,746.0; the written zero shows one decimal place.', '857 386 321 à trois chiffres significatifs garde 857 ; le chiffre suivant est 3 : le résultat est 857 000 000. Pour 98 745,9674 à deux décimales, garde ,96 puis regarde 7 : le résultat est 98 745,97. À une décimale, ,9 produit une retenue et donne 98 746,0 ; le zéro écrit indique une décimale.'),
    question: tx('Round 857,386,321 to three significant figures.', 'Arrondis 857 386 321 à trois chiffres significatifs.'), options: { en: ['857,000,000', '857', '858,000,000'], fr: ['857 000 000', '857', '858 000 000'] },
    correction: tx('Start counting at the first non-zero digit: 8, 5, 7 are retained. The next digit 3 does not increase 7. Six whole-number places remain, so write six zeros. Writing only 857 would change the magnitude.', 'Compte depuis le premier chiffre non nul : 8, 5 et 7 sont conservés. Le suivant, 3, ne fait pas augmenter 7. Il reste six positions entières : écris six zéros. Écrire seulement 857 changerait l’ordre de grandeur.'),
    tasks: [tx('Independently express 857,386,321 to five, four and three significant figures. Express 98,745.9674 to three, two and one decimal places. Mark the retained digit and next digit in each working and explain any carry to your teacher.', 'Exprime seul 857 386 321 à cinq, quatre puis trois chiffres significatifs. Exprime 98 745,9674 à trois, deux puis une décimale. Marque les chiffres conservés et le suivant et explique les retenues à l’enseignant.'), tx('Round 6,789,450 to four significant figures and 37.9952 to two decimal places. Explain why whole-number zeros and a decimal carry must be preserved. Submit your independent workings.', 'Arrondis 6 789 450 à quatre chiffres significatifs et 37,9952 à deux décimales. Explique les zéros entiers et la retenue décimale. Présente tes calculs personnels.')],
    transfer: [tx('A fictional measurement is 24.678 litres. Report it to two decimal places and two significant figures, clearly distinguish the instructions and explain why rounded values are estimates. Show independent workings.', 'Une mesure fictive vaut 24,678 litres. Donne-la à deux décimales et à deux chiffres significatifs, distingue les consignes et explique pourquoi ce sont des estimations. Montre les calculs.'), tx('Create an integer whose rounding to three significant figures requires carrying across a 9. Show the calculation and check that its order of magnitude stays appropriate.', 'Crée un entier dont l’arrondi à trois chiffres significatifs nécessite une retenue sur un 9. Montre le calcul et vérifie l’ordre de grandeur.')],
    retention: [tx('Where do you start counting significant figures?', 'Où commence-t-on à compter les chiffres significatifs ?'), tx('Round 12.346 to two decimal places.', 'Arrondis 12,346 à deux décimales.')],
    retentionOptions: [{ en: ['At the first non-zero digit', 'Always after the decimal point', 'At the last digit only'], fr: ['Au premier chiffre non nul', 'Toujours après la virgule', 'Seulement au dernier chiffre'] }, { en: ['12.35', '12.34', '12.3'], fr: ['12,35', '12,34', '12,3'] }],
    criteria: [tx('Inspect independent calculations for significant figures, decimal positions, rounding decisions, carries and magnitude.', 'Examiner les calculs autonomes : chiffres significatifs, positions décimales, décisions d’arrondi, retenues et ordre de grandeur.'), tx('Require explanations distinguishing the two instructions rather than selected results alone.', 'Exiger une distinction expliquée entre les deux consignes, pas seulement des résultats choisis.')],
  },
  {
    id: 'competency-gh-computing-b7-nacca2020-p031-r01', title: tx('Microprocessors and fourth-generation computers', 'Microprocesseurs et ordinateurs de quatrième génération'),
    explanation: tx('A microprocessor puts the central processing functions on an integrated circuit, often called a chip. Fourth-generation computers are associated with microprocessors and the growth of personal computers. The processor executes instructions; it is not the same as the keyboard, screen or permanent file storage. In a simplified model, the control unit coordinates instructions, the arithmetic and logic unit performs operations, and registers temporarily hold small amounts of working data. This is a teaching model, not a complete modern processor design. Observe a teacher-approved photograph or sealed device; do not open electrical equipment.', 'Un microprocesseur réunit les fonctions centrales de traitement sur un circuit intégré, souvent appelé puce. La quatrième génération est associée aux microprocesseurs et au développement des ordinateurs personnels. Le processeur exécute des instructions ; ce n’est ni le clavier, ni l’écran, ni le stockage permanent. Dans un modèle simplifié, l’unité de commande coordonne, l’unité arithmétique et logique effectue des opérations et les registres gardent temporairement quelques données. Ce modèle pédagogique ne décrit pas toute une architecture moderne. Observe une photo approuvée ou un appareil fermé ; n’ouvre aucun équipement électrique.'),
    example: tx('When a school computer adds 18 and 24, an input device supplies data, the processor follows the addition instruction, working values are held temporarily, and an output device shows 42. Point to the processor in an approved labelled image and sketch this simplified flow. The screen displays the result; it does not replace the processor.', 'Quand un ordinateur scolaire additionne 18 et 24, un périphérique fournit les données, le processeur exécute l’addition, des valeurs sont gardées temporairement et un périphérique affiche 42. Repère le processeur sur une image légendée approuvée et dessine ce circuit simplifié. L’écran affiche le résultat ; il ne remplace pas le processeur.'),
    question: tx('Which component carries out the instructions for an addition?', 'Quel composant exécute les instructions d’une addition ?'), options: { en: ['The processor', 'The screen alone', 'The keyboard alone'], fr: ['Le processeur', 'L’écran seul', 'Le clavier seul'] },
    correction: tx('Trace input, processing and output separately. Keys enter data and a screen displays results. The processor executes instructions. Explain that distinction in your own words, then retry.', 'Distingue entrée, traitement et sortie. Les touches saisissent les données et l’écran affiche le résultat. Le processeur exécute les instructions. Explique la différence, puis réessaie.'),
    tasks: [tx('Using a teacher-approved image, identify a microchip and explain its relationship to a microprocessor. Draw a simplified processor with control unit, arithmetic and logic unit and registers. Discuss fourth-generation features. Your teacher must inspect the diagram and hear your explanation.', 'Sur une image approuvée, identifie une puce et explique son lien avec le microprocesseur. Dessine un processeur simplifié avec unité de commande, unité arithmétique et logique et registres. Présente les caractéristiques de la quatrième génération. L’enseignant examine le dessin et écoute l’explication.'), tx('Independently explain how a school computer processes an arithmetic instruction, distinguishing processor, input, output and storage. Use a labelled diagram and relate the microprocessor to fourth-generation computers. Request teacher review.', 'Explique seul le traitement d’une instruction arithmétique dans un ordinateur scolaire, en distinguant processeur, entrée, sortie et stockage. Utilise un schéma légendé et relie le microprocesseur à la quatrième génération. Demande un examen par l’enseignant.')],
    transfer: [tx('Use a different teacher-approved device diagram. Locate its processor and explain a possible input-processing-output flow. State which details the simplified diagram does not establish.', 'Avec le schéma approuvé d’un autre appareil, repère le processeur et explique un circuit entrée-traitement-sortie possible. Précise les limites du schéma simplifié.'), tx('A classmate calls the monitor the processor. Explain the error with a new example and an independently drawn labelled diagram. Show the actual work to your teacher.', 'Un camarade appelle le moniteur « processeur ». Explique l’erreur avec un nouvel exemple et un schéma personnel légendé. Présente le vrai travail à l’enseignant.')],
    retention: [tx('Which development is associated with fourth-generation computers?', 'Quelle évolution est associée à la quatrième génération ?'), tx('Which simplified processor part performs arithmetic and logical operations?', 'Quelle partie simplifiée effectue les opérations arithmétiques et logiques ?')],
    retentionOptions: [{ en: ['Microprocessors', 'Only paper storage', 'Replacing every processor with a screen'], fr: ['Les microprocesseurs', 'Seulement le stockage sur papier', 'Le remplacement de tout processeur par un écran'] }, { en: ['Arithmetic and logic unit', 'Printer tray', 'Mouse cable'], fr: ['L’unité arithmétique et logique', 'Le bac de l’imprimante', 'Le câble de la souris'] }],
    criteria: [tx('Check the actual labelled image/diagram and an independent explanation of processor parts and generation features.', 'Vérifier l’image ou le schéma légendé et l’explication autonome des parties et des caractéristiques de la génération.'), tx('Require accurate distinctions between processing, input, output and storage without treating a simplified model as a complete chip design.', 'Exiger des distinctions exactes entre traitement, entrée, sortie et stockage sans présenter le modèle simplifié comme un plan complet de puce.')],
  },
  register(7, '038', tx('At school, Ama says to a friend, “Hi Kojo, can you help me?” At the office she says, “Good morning. Could you help me find the timetable, please?” The purpose is similar, but the relationship and setting change. Practise both with a partner and swap roles.', 'À l’école, Ama dit à un ami : « Hi Kojo, can you help me? » Au secrétariat : « Good morning. Could you help me find the timetable, please? » Le but est proche, mais la relation et le contexte changent. Jouez les deux échanges, puis inversez les rôles.'),
    [tx('Hold two short English conversations: greet and request help from a classmate, then from a school office worker. Respond to your partner’s unscripted question. Your teacher must listen and record what you actually said.', 'Tiens deux courts échanges en anglais : salue un camarade et demande son aide, puis adresse-toi à un agent du secrétariat. Réponds à une question imprévue. L’enseignant doit écouter et noter les paroles réellement prononcées.'), tx('In English, encourage a teammate and then make a formal classroom announcement. Explain your language choices to your teacher. A written response only requests review; it does not replace speaking.', 'En anglais, encourage un coéquipier, puis fais une annonce formelle en classe. Justifie tes choix à l’enseignant. Une réponse écrite demande seulement un examen ; elle ne remplace pas la parole.')],
    [tx('Independently role-play asking a visitor for directions in English, then greeting a close relative. Adapt your language and answer a follow-up question while your teacher listens.', 'Joue seul en anglais une demande d’itinéraire à un visiteur, puis une salutation à un proche. Adapte le langage et réponds à une question complémentaire devant l’enseignant.'), tx('In a new school situation chosen by your teacher, greet, make a request and close the conversation in English. Explain which register you chose and why.', 'Dans une nouvelle situation scolaire choisie par l’enseignant, salue, formule une demande et termine l’échange en anglais. Justifie ton registre.')]),
  register(8, '074', tx('A football discussion with a friend may begin “That was a great goal!” An invitation to a district official could begin “Good morning. Our school would like to invite you to our exhibition.” The official needs the event, date and a clear request. Practise the invitation and answer your partner’s questions.', 'Avec un ami, une discussion de football peut commencer par « That was a great goal! » Une invitation à un responsable local pourrait commencer par « Good morning. Our school would like to invite you to our exhibition. » Il faut préciser l’événement, la date et la demande. Pratique l’invitation et réponds aux questions.'),
    [tx('With a partner, hold an informal English conversation about a school football match, then formally invite a district official to a school event. Your teacher must observe both and ask an unscripted follow-up.', 'Avec un partenaire, converse en anglais de façon informelle sur un match scolaire, puis invite formellement un responsable local à une activité. L’enseignant doit observer les deux échanges et poser une question imprévue.'), tx('Role-play an English enquiry at a travel office about a school visit, then discuss the plan informally with a friend. Give clear details and respond appropriately. Teacher observation is required.', 'Joue en anglais une demande d’information dans une agence pour une visite scolaire, puis discute du projet avec un ami. Donne des détails clairs et réponds de façon adaptée. Observation de l’enseignant requise.')],
    [tx('In English, adjust the same invitation for a friend and an unfamiliar adult. Respond to each partner’s question and justify the differences to your teacher.', 'En anglais, adapte la même invitation à un ami et à un adulte inconnu. Réponds aux questions et justifie les différences à l’enseignant.'), tx('For a new school event, make a formal English invitation without copying the worked example. Discuss the event informally afterwards; teacher observation is required.', 'Pour une nouvelle activité scolaire, formule une invitation formelle en anglais sans copier l’exemple. Discute ensuite de l’activité de manière informelle devant l’enseignant.')]),
  register(9, '106', tx('In a skit about organising a school music event, friends might say “Let’s sort out the playlist.” A student addressing the headteacher could say “We propose a lunchtime performance and would appreciate your permission.” Keep each character’s register consistent, then respond naturally when the plan changes. Slang varies by community and can exclude listeners; explain rather than assume it is understood.', 'Dans une saynète sur une activité musicale scolaire, des amis pourraient dire « Let’s sort out the playlist. » Devant la direction : « We propose a lunchtime performance and would appreciate your permission. » Garde un registre cohérent pour chaque personnage, puis réagis naturellement à un changement. L’argot varie selon la communauté ; explique-le au lieu de supposer qu’il est compris.'),
    [tx('Create and act an English skit about a school club with both formal and informal characters. Respond spontaneously when your teacher introduces a change. Explain any slang or jargon and whether your audience understands it.', 'Crée et joue une saynète en anglais sur un club scolaire avec des personnages formels et informels. Réagis spontanément à un changement introduit par l’enseignant. Explique l’argot ou le jargon et vérifie sa compréhension.'), tx('Discuss a grade-appropriate school issue in English with two partners. Adapt register when addressing a peer and a school official. Your teacher must hear your spontaneous responses and explanations.', 'Discute en anglais d’un sujet scolaire adapté avec deux partenaires. Adapte le registre entre un camarade et un responsable scolaire. L’enseignant doit entendre tes réponses spontanées et tes justifications.')],
    [tx('Act a new English scene about improving participation in a school event. Switch appropriately between peer and official interactions without rehearsing every response; teacher observation is required.', 'Joue une nouvelle scène en anglais sur la participation à une activité scolaire. Passe d’un échange entre camarades à un échange officiel sans répéter toutes les réponses à l’avance ; observation requise.'), tx('Evaluate a new English dialogue supplied by your teacher, explain whose language needs adapting and perform an improved version with spontaneous follow-up.', 'Évalue un nouveau dialogue anglais fourni par l’enseignant, justifie les adaptations et joue une version améliorée avec des réponses spontanées.')]),
  {
    id: 'competency-gh-mathematics-b7-nacca2020-p034-r01', title: tx('Rounding large whole numbers', 'Arrondir de grands nombres entiers'),
    explanation: tx('Locate the two neighbouring multiples of the requested unit. Rounding down chooses the lower multiple; rounding up chooses the upper multiple when the number is not already exact. Rounding off chooses the nearer multiple; at a halfway point use the usual school convention of choosing the upper multiple for positive numbers. Keep the requested place value clear. Work with numbers above one billion as the indicator specifies.', 'Repère les deux multiples voisins de l’unité demandée. Arrondir par défaut choisit le multiple inférieur ; par excès choisit le supérieur lorsque le nombre n’est pas déjà exact. L’arrondi au plus proche choisit le voisin le plus proche ; à mi-chemin, utilise la convention scolaire habituelle du voisin supérieur pour les nombres positifs. Précise la position demandée. Travaille au-delà d’un milliard, comme l’indicateur le demande.'),
    example: tx('Round 1,234,567,890 to the nearest hundred thousand. The neighbours are 1,234,500,000 and 1,234,600,000. Distances are 67,890 and 32,110, so the nearest is 1,234,600,000. Down gives 1,234,500,000; up gives 1,234,600,000. The remaining digits become zeros, not deleted places.', 'Arrondis 1 234 567 890 à la centaine de milliers. Les voisins sont 1 234 500 000 et 1 234 600 000. Les distances sont 67 890 et 32 110 : le plus proche est 1 234 600 000. Par défaut : 1 234 500 000 ; par excès : 1 234 600 000. Les chiffres restants deviennent des zéros, sans supprimer les positions.'),
    question: tx('Round 1,234,567,890 to the nearest hundred thousand.', 'Arrondis 1 234 567 890 à la centaine de milliers.'), options: { en: ['1,234,600,000', '1,234,500,000', '1,234,568'], fr: ['1 234 600 000', '1 234 500 000', '1 234 568'] },
    correction: tx('Write both hundred-thousand neighbours. Compare distances: 32,110 to the upper neighbour is less than 67,890 to the lower. Keep every place and replace the trailing digits with zeros. Choosing the lower neighbour is rounding down here, not rounding to the nearest.', 'Écris les deux multiples voisins de 100 000. La distance au supérieur, 32 110, est inférieure à 67 890. Garde toutes les positions et remplace la fin par des zéros. Choisir le voisin inférieur est ici un arrondi par défaut, pas au plus proche.'),
    tasks: [tx('Independently round 2,345,678,912 off, up and down to the nearest hundred thousand and ten thousand. Show neighbours and justify each choice. Then express the number to five significant figures. Submit your written workings for teacher review.', 'Arrondis seul 2 345 678 912 au plus proche, par excès et par défaut à 100 000 puis à 10 000. Montre les voisins et justifie tes choix. Exprime ensuite le nombre avec cinq chiffres significatifs. Présente tes calculs à l’enseignant.'), tx('For 3,876,543,210, show rounding to the nearest thousand, hundred and ten, then to four significant figures. Explain how rounding up differs from rounding off. Written reasoning needs teacher review.', 'Pour 3 876 543 210, montre l’arrondi au millier, à la centaine et à la dizaine, puis à quatre chiffres significatifs. Explique la différence entre par excès et au plus proche. Examen des calculs par l’enseignant requis.')],
    transfer: [tx('A fictional national materials budget is GH₵2,845,321,678. Report estimates to the nearest hundred thousand and thousand, label them as estimates, and explain which loses more precision. Show your work.', 'Un budget national fictif de matériaux vaut 2 845 321 678 GH₵. Donne des estimations à 100 000 et à 1 000, indique qu’elles sont arrondies et explique laquelle perd le plus de précision. Montre les calculs.'), tx('Create a whole number above one billion for which rounding up and rounding off to ten thousand differ. Prove it using neighbouring multiples and explain a case where they agree.', 'Crée un entier supérieur à un milliard dont les arrondis par excès et au plus proche à 10 000 diffèrent. Démontre-le avec les voisins et explique un cas où ils coïncident.')],
    retention: [tx('What does rounding down choose for a positive number between two multiples?', 'Que choisit l’arrondi par défaut entre deux multiples positifs ?'), tx('Round 2,345,678,901 to the nearest thousand.', 'Arrondis 2 345 678 901 au millier le plus proche.')],
    retentionOptions: [{ en: ['The lower multiple', 'Always the upper multiple', 'Remove every zero'], fr: ['Le multiple inférieur', 'Toujours le multiple supérieur', 'Supprimer tous les zéros'] }, { en: ['2,345,679,000', '2,345,678,000', '2,345,679'], fr: ['2 345 679 000', '2 345 678 000', '2 345 679'] }],
    criteria: [tx('Check place-value neighbours, rounding direction, retained positions and significant figures against the actual written workings.', 'Vérifier les voisins, le sens de l’arrondi, les positions conservées et les chiffres significatifs dans les vrais calculs.'), tx('Require the learner’s independent explanation; a selected numerical answer alone is insufficient.', 'Exiger une explication personnelle ; un résultat choisi seul ne suffit pas.')],
  },
];
